<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\User\Infrastructure\Driven;

use Override;
use DateInterval;
use DateTimeImmutable;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Security\PasswordHasher;
use Civi\Lughauth\Shared\Security\SecretDigester;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\UserApproveOptions;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserPasswordVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\Gateway\UserAcceptedTermsOfUseCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\UserAcceptedTermsOfUse;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\UserAcceptedTermsOfUseAttributes;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\Gateway\UserAccessTemporalCodeCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driven\UserLoaderAdapter;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\RegisterUserGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\RegistrationNotificationData;

class RegisterUserAdapter implements RegisterUserGateway
{
    public function __construct(
        private readonly UserLoaderAdapter $users,
        private readonly TenantConfigQueryRepositoryGateway $configs,
        private readonly UserCommandRepositoryGateway $repository,
        private readonly UserAccessTemporalCodeCommandRepositoryGateway $codes,
        private readonly PasswordHasher $hasher,
        private readonly SecretDigester $digester,
        private readonly UserAcceptedTermsOfUseCommandRepositoryGateway $writerUserTerms,
        private readonly Random $randomizer,
    ) {
    }

    #[Override]
    public function allowRegister(string $tenant): bool
    {
        $theTenant = $this->users->checkTenant($tenant, '-');
        $conf = $this->configs->findOneByTenant($theTenant);
        return ($conf && $conf->isAllowRegister());
    }

    /**
     * @return string
     */
    #[Override]
    public function getRegisterConsent(string $tenant): ?string
    {
        $theTenant = $this->users->checkTenant($tenant, '-');
        $terms = $this->users->loadTenantTerms($theTenant, []);
        $first = $terms[0] ?? null;
        return $first !== null ? $first->getText() : '';
    }

    #[Override]
    public function requestForRegister(string $url, string $tenant, string $email, string $password): ?RegistrationNotificationData
    {
        $theTenant = $this->users->checkTenant($tenant, '-');
        $conf = $this->configs->findOneByTenant($theTenant);
        if (!$conf || !$conf->isAllowRegister()) {
            return null;
        }
        try {
            $termsList = $this->users->loadTenantTerms($theTenant, []);
            $terms = $termsList[0] ?? null;
            $theUser = $this->repository->create(User::register(
                uid:  $this->randomizer->comb(),
                name: $email,
                email: $email,
                hasher: $this->hasher,
                password: $password,
                tenant: $theTenant
            ));
            if ($terms !== null) {
                $acepted = new UserAcceptedTermsOfUseAttributes();
                $acepted->uid(Random::comb());
                $acepted->user($theUser);
                $acepted->conditions($terms);
                $acepted->acceptDate(new DateTimeImmutable());
                $this->writerUserTerms->create(UserAcceptedTermsOfUse::create($acepted));
            }
            $verify = md5($this->randomizer->comb());
            $activateUrl = str_ends_with($url, '=') ? $url . $verify : $url;
            $code = $this->users->userCodeForUpdate($theUser);
            $this->users->updateCode($code->generatedRegisterVerification($this->digester, $verify, $url, new DateTimeImmutable()->add(new DateInterval("P1D"))));
            return new RegistrationNotificationData(
                email: $email,
                name: $email,
                tenant: new TenantRef($theTenant->uid()),
                activateUrl: $activateUrl,
            );
        } catch (ConstraintException $ex) {
            if (!$ex->includeViolationCode('not-unique')) {
                throw $ex;
            }
            $theUser = $this->repository->findOneForUpdateByTenantAndName($theTenant, $email);
            if ($theUser === null || $theUser->getApprove() !== UserApproveOptions::UNVERIFIED) {
                return null;
            }
            $att = $theUser->toAttributes();
            $att->password(UserPasswordVO::fromPlainText($this->hasher, $password));
            $updated = $this->repository->update($theUser, $theUser->replace($att));
            $verify = md5($this->randomizer->comb());
            $activateUrl = str_ends_with($url, '=') ? $url . $verify : $url;
            $code = $this->users->userCodeForUpdate($updated);
            $this->users->updateCode($code->generatedRegisterVerification($this->digester, $verify, $url, new DateTimeImmutable()->add(new DateInterval("P1D"))));
            return new RegistrationNotificationData(
                email: $email,
                name: $theUser->getName() ?? $email,
                tenant: new TenantRef($theTenant->uid()),
                activateUrl: $activateUrl,
            );
        }
    }

    #[Override]
    public function verifyRegister(string $tenant, string $code): ?string
    {
        $theTenant = $this->users->checkTenant($tenant, '-');
        [$user, $userCode] = $this->users->checkUserByRegisterCode($theTenant, $code);
        if (!$userCode->verifyRegisterCode($this->digester, $code)) {
            return null;
        }
        $conf = $this->configs->findOneByTenant($theTenant);
        $this->repository->update($user, $user->verify(
            $conf?->isEnableRegisterUsers() ? UserApproveOptions::ACCEPTED : UserApproveOptions::PENDING
        ));
        $this->codes->update($userCode, $userCode->resetRegisterVerification());
        return $user->getName();
    }
}
